section.sourcecode:
sha256 = bstr .size 32

digest = {
  "algorithm": "sha-256",
  "value": sha256
}

; spt-1 remains the initial plain-text Portable Text-shaped profile.
hail-body-spt-1 = {
  "version": 1,
  "profile": "spt-1",
  "blocks": [* spt-1-text-block]
}

spt-1-text-block = {
  "_type": "block",
  "style": "normal",
  "children": [1* spt-1-span],
  "markDefs": []
}

spt-1-span = {
  "_type": "span",
  "text": tstr,
  "marks": []
}

; spt-2 adds a closed set of styles, lists, decorators
; and HTTPS links.
hail-body-spt-2 = {
  "version": 1,
  "profile": "spt-2",
  "blocks": [* spt-2-text-block]
}

spt-2-text-block = {
  "_type": "block",
  "style": "normal" / "h1" / "h2" / "h3" / "blockquote" / "caption",
  "children": [1* spt-2-span],
  "markDefs": [* spt-link],
  ? "listItem": "bullet" / "number",
  ? "level": 1..3
}

spt-2-span = {
  "_type": "span",
  "text": tstr,
  "marks": [* tstr]
}

spt-link = {
  "_key": tstr,
  "_type": "spt.link",
  "href": tstr,
  ? "title": tstr
}

; spt-3 adds one bundled, digest-bound header image before rich text.
hail-body-spt-3 = {
  "version": 1,
  "profile": "spt-3",
  "assets": asset-manifest-v1,
  "blocks": [spt-image-block, * spt-2-text-block]
}

spt-image-block = {
  "_type": "spt.image",
  "asset": tstr,
  "alt": tstr,
  ? "caption": tstr
}

; Reusable bundled-image manifest for future body
; and profile versions.
asset-manifest-v1 = {
  "version": 1,
  "assets": [1*2 bundled-image-asset-v1]
}

bundled-image-asset-v1 = {
  "id": tstr,
  "role": "avatar" / "header",
  "media_type": "image/png",
  "loading": "bundled",
  "size": 1..196608,
  "digest": digest,
  "width": 1..2400,
  "height": 1..1200,
  "data": bstr
}
